toolUseResult.originalFile:
import Phaser from 'phaser';
import { type BattleChannel } from '../utils/battleChannel';
import { BattleEvent, BattleResult } from '../types/BattleTypes';
import { GameMode, Difficulty } from '../types/GameMode';
import { POOP_CONFIG } from '../config/poop';
import type Poop from '../objects/Poop';
import GameScene from './GameScene';

interface BattleInitData {
  gameMode?: string;
  difficulty?: string;
  purePhysical?: boolean;
  battleChannel?: BattleChannel;
  isHost?: boolean;
  opponentId?: string;
  roomCode?: string;
}

/**
 * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
 *
 * 추가 기능:
 * - 상대 점수 실시간 표시
 * - 특수 똥 수집 시 상대에게 일반 똥 전송
 * - 상대 사망 시 즉시 승리
 * - 상대 연결 끊김 시 5초 대기 후 부전승
 */
export default class BattleGameScene extends GameScene {
  private battleChannel: BattleChannel | null = null;
  private isHost: boolean = false;
  private opponentId: string = '';
  private roomCode: string = '';
  private opponentScore: number = 0;
  private opponentScoreText!: Phaser.GameObjects.Text;
  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private battleFinished: boolean = false;

  constructor() {
    super();
    // 씬 키를 오버라이드 — Phaser는 마지막 생성된 key를 사용
  }

  // Phaser 씬 키 재정의
  get sys(): Phaser.Scenes.Systems {
    return super.sys;
  }

  init(data: BattleInitData) {
    // 대전 모드 전용 데이터 추출 (super.init 호출 전)
    this.battleChannel = (data.battleChannel as BattleChannel) ?? null;
    this.isHost = data.isHost ?? false;
    this.opponentId = data.opponentId ?? '';
    this.roomCode = data.roomCode ?? '';
    this.opponentScore = 0;
    this.battleFinished = false;

    // 부모 init 호출: EXTREME 난이도 고정, BATTLE 모드
    super.init({
      gameMode: GameMode.BATTLE,
      difficulty: Difficulty.EXTREME,
      purePhysical: false,
    });
  }

  create() {
    super.create();

    // 상대 점수 UI (HUD 바 내부, 중앙 상단)
    this.opponentScoreText = this.add.text(200, 3, '상대: 0', {
      fontSize: '14px',
      color: '#ff6666',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 3,
    }).setOrigin(0.5, 0).setDepth(10);

    // ── 배틀 채널 이벤트 리스너 ──
    this.setupBattleListeners();

    // 1초마다 점수 브로드캐스트
    this.scoreUpdateTimer = this.time.addEvent({
      delay: 1000,
      callback: () => {
        if (!this.gameOver && this.battleChannel) {
          this.battleChannel.sendScoreUpdate(this.score);
        }
