  }

  private showReceiveWarning() {
    const border = this.add.rectangle(200, 300, 400, 600)
      .setStrokeStyle(6, 0xff0000)
      .setFillStyle(0xff0000, 0.1)
      .setDepth(150);

    this.tweens.add({
      targets: border,
      alpha: 0,
      duration: 400,
      onComplete: () => border.destroy(),
    });

