      this.sound.stopAll();
    }

    // 약간의 딜레이 후 결과 씬으로
    this.time.delayedCall(1000, () => {
      const channel = this.battleChannel;
      this.battleChannel = null; // 소유권 이전
      this.scene.start('BattleResultScene', {
        result,
