import Phaser from 'phaser';
import { BattleChannel } from '../utils/battleChannel';
import { BattleEvent } from '../types/BattleTypes';
import { getSafeSelectedCharacter } from '../utils/character';
import { supabase } from '../utils/supabase';
import BaseScene from './BaseScene';

/**
 * 대전 매칭 씬
 * - 방 만들기: 4자리 코드 생성 → 대기
 * - 방 참가: 코드 입력 → 대기
 * - 양쪽 ready 교환 → 3초 카운트다운 → BattleGameScene 전환
 */
export default class BattleMatchScene extends BaseScene {
  private battleChannel: BattleChannel | null = null;
  private statusText!: Phaser.GameObjects.Text;
  private codeText!: Phaser.GameObjects.Text;
  private inputElement: HTMLInputElement | null = null;
  private isHost: boolean = false;
  private opponentId: string = '';
  private myReady: boolean = false;
  private opponentReady: boolean = false;
  private userId: string = '';

  constructor() {
    super('BattleMatchScene');
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
  }

  async create() {
    super.create();

    // 배경
    const bg = this.add.image(200, 300, 'background2');
    bg.setDisplaySize(400, 600);

    // 반투명 오버레이
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.6);

    // 타이틀
    this.add.text(200, 60, '⚔️ 대전 모드', {
      fontSize: '32px',
      color: '#ff4444',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
    }).setOrigin(0.5);

    this.add.text(200, 105, 'EXTREME 난이도로 1대1 대전!', {
      fontSize: '14px',
      color: '#cccccc',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 상태 텍스트 (오버레이 위에 표시되도록 depth 설정)
    this.statusText = this.add.text(200, 400, '', {
      fontSize: '16px',
      color: '#ffffff',
      stroke: '#000',
      strokeThickness: 3,
      align: 'center',
    }).setOrigin(0.5).setDepth(10);

    // 방 코드 표시 (오버레이 위에 표시되도록 depth 설정)
    this.codeText = this.add.text(200, 280, '', {
      fontSize: '48px',
      color: '#FFD700',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 6,
      letterSpacing: 8,
    }).setOrigin(0.5).setDepth(10);

    // 방 만들기 버튼
    this.createButton(200, 220, '방 만들기', 0xe74c3c, () => this.handleCreateRoom());

    // 방 참가 버튼
    this.createButton(200, 310, '방 참가', 0x3498db, () => this.handleJoinRoom());

    // 뒤로가기 버튼
    const backBtn = this.add.text(200, 550, '← 메인 메뉴', {
      fontSize: '18px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });

    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    backBtn.on('pointerdown', () => this.goBack());

    // 유저 ID 가져오기
    const { data } = await supabase.auth.getUser();
    this.userId = data.user?.id ?? `anon-${Date.now()}`;
  }

  private createButton(x: number, y: number, label: string, color: number, onClick: () => void) {
    const btn = this.add.rectangle(x, y, 250, 60, color);
    btn.setStrokeStyle(3, 0xffffff);
    const txt = this.add.text(x, y, label, {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold',
    }).setOrigin(0.5);

    btn.setInteractive({ useHandCursor: true });
    btn.on('pointerover', () => { btn.setAlpha(0.8); txt.setScale(1.05); });
    btn.on('pointerout', () => { btn.setAlpha(1); txt.setScale(1); });
    btn.on('pointerdown', () => onClick());

    return { btn, txt };
  }

  private async handleCreateRoom() {
    if (this.battleChannel) return;

    this.isHost = true;
    const code = BattleChannel.generateRoomCode();
    this.battleChannel = new BattleChannel();
    this.battleChannel.createRoom(code, this.userId);

    // ⚠️ 리스너 등록 → subscribe 순서 (Supabase Realtime 필수 패턴)
    this.setupChannelListeners();
    await this.battleChannel.subscribe();

    // UI 갱신: 버튼 영역 지우고 대기 화면
    this.clearMainUI();
    this.codeText.setText(code);
    this.statusText.setText('상대방에게 코드를 알려주세요\n대기 중...');
  }

  private async handleJoinRoom() {
    if (this.battleChannel) return;

    // HTML input 생성
    this.clearMainUI();
    this.statusText.setText('방 코드를 입력하세요');

    this.showCodeInput();
  }

  private showCodeInput() {
    const canvas = this.game.canvas;
    const rect = canvas.getBoundingClientRect();
    const scaleX = rect.width / 400;
    const scaleY = rect.height / 600;

    const input = document.createElement('input');
    input.type = 'text';
    input.maxLength = 4;
    input.placeholder = 'CODE';
    input.style.cssText = `
      position: fixed;
      left: ${rect.left + 200 * scaleX}px;
      top: ${rect.top + 300 * scaleY}px;
      transform: translateX(-50%);
      width: ${Math.round(180 * scaleX)}px;
      height: ${Math.round(50 * scaleY)}px;
      font-size: ${Math.round(28 * scaleY)}px;
      text-align: center;
      text-transform: uppercase;
      border: 3px solid #FFD700;
      border-radius: 10px;
      background: #1a1a2e;
      color: #FFD700;
      font-weight: bold;
      letter-spacing: ${Math.round(8 * scaleX)}px;
      outline: none;
      z-index: 9999;
    `;
    document.body.appendChild(input);
    input.focus();
    this.inputElement = input;

    input.addEventListener('input', () => {
      input.value = input.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
    });

    // 참가 버튼
    const joinBtn = this.add.rectangle(200, 400, 200, 50, 0x27ae60);
    joinBtn.setStrokeStyle(2, 0xffffff);
    const joinTxt = this.add.text(200, 400, '참가', {
      fontSize: '20px',
      color: '#ffffff',
      fontStyle: 'bold',
    }).setOrigin(0.5);
    joinBtn.setInteractive({ useHandCursor: true });

    const doJoin = async () => {
      const code = input.value.trim().toUpperCase();
      if (code.length !== 4) {
        this.statusText.setText('4자리 코드를 입력하세요');
        return;
      }
      this.isHost = false;
      this.battleChannel = new BattleChannel();
      await this.battleChannel.joinRoom(code, this.userId);
      this.removeInput();
      joinBtn.destroy();
      joinTxt.destroy();
      this.codeText.setText(code);
      this.statusText.setText('방에 참가했습니다\n준비 중...');
      this.setupChannelListeners();

      // 참가 후 바로 ready 전송
      this.time.delayedCall(500, () => {
        this.sendReady();
      });
    };

    joinBtn.on('pointerdown', doJoin);
    input.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') doJoin();
    });
  }

  private setupChannelListeners() {
    if (!this.battleChannel) return;

    // 상대 참가 감지 (호스트일 때)
    this.battleChannel.onPresenceJoin((userId) => {
      this.opponentId = userId;
      if (this.isHost) {
        this.statusText.setText('상대방 입장!\n준비 중...');
        // 호스트도 ready 전송
        this.time.delayedCall(500, () => {
          this.sendReady();
        });
      }
    });

    // 상대 이탈 감지
    this.battleChannel.onPresenceLeave(() => {
      this.statusText.setText('상대방이 나갔습니다');
      this.opponentReady = false;
    });

    // Ready 이벤트
    this.battleChannel.onEvent(BattleEvent.READY, (payload) => {
      this.opponentId = payload.userId;
      this.opponentReady = true;
      this.checkBothReady();
    });

    // 게임 시작 이벤트 (호스트가 보냄)
    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
      this.startCountdown();
    });
  }

  private sendReady() {
    if (!this.battleChannel || this.myReady) return;
    this.myReady = true;
    const charId = getSafeSelectedCharacter();
    this.battleChannel.sendReady(charId);
    this.statusText.setText('준비 완료!\n상대를 기다리는 중...');
    this.checkBothReady();
  }

  private checkBothReady() {
    if (this.myReady && this.opponentReady && this.isHost) {
      // 호스트가 game-start 발신
      this.battleChannel?.sendGameStart(Date.now());
      this.startCountdown();
    }
  }

  private startCountdown() {
    this.codeText.setText('');
    this.statusText.setText('');

    let count = 3;
    const countText = this.add.text(200, 300, `${count}`, {
      fontSize: '80px',
      color: '#ff4444',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 8,
    }).setOrigin(0.5);

    const timer = this.time.addEvent({
      delay: 1000,
      callback: () => {
        count--;
        if (count > 0) {
          countText.setText(`${count}`);
        } else {
          countText.setText('GO!');
          timer.remove();
          this.time.delayedCall(500, () => {
            this.goToBattle();
          });
        }
      },
      repeat: 2,
    });
  }

  private goToBattle() {
    this.scene.start('BattleGameScene', {
      battleChannel: this.battleChannel,
      isHost: this.isHost,
      opponentId: this.opponentId,
      roomCode: this.battleChannel?.code ?? '',
    });
    // 채널 소유권을 BattleGameScene에 이전 — 여기서 destroy하지 않음
    this.battleChannel = null;
  }

  private clearMainUI() {
    // 기존 버튼(y=220,h=60 / y=310,h=60) 위에 오버레이를 덮어 가림
    // 범위: y=190~340 → center=265, h=150
    this.add.rectangle(200, 265, 310, 150, 0x000000, 0.95).setDepth(5);
  }

  private removeInput() {
    if (this.inputElement) {
      this.inputElement.remove();
      this.inputElement = null;
    }
  }

  private async goBack() {
    this.removeInput();
    if (this.battleChannel) {
      await this.battleChannel.destroy();
      this.battleChannel = null;
    }
    this.scene.start('ModeSelectScene');
  }

  shutdown() {
    this.removeInput();
  }
}

