  1→import Phaser from 'phaser';
  2→import { type BattleChannel } from '../utils/battleChannel';
  3→import { BattleEvent, BattleResult } from '../types/BattleTypes';
  4→import { GameMode, Difficulty } from '../types/GameMode';
  5→import { POOP_CONFIG } from '../config/poop';
  6→import type Poop from '../objects/Poop';
  7→import GameScene from './GameScene';
  8→
  9→interface BattleInitData {
 10→  gameMode?: string;
 11→  difficulty?: string;
 12→  purePhysical?: boolean;
 13→  battleChannel?: BattleChannel;
 14→  isHost?: boolean;
 15→  opponentId?: string;
 16→  roomCode?: string;
 17→}
 18→
 19→/**
 20→ * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
 21→ *
 22→ * 추가 기능:
 23→ * - 상대 점수 실시간 표시
 24→ * - 특수 똥 수집 시 상대에게 일반 똥 전송
 25→ * - 상대 사망 시 즉시 승리
 26→ * - 상대 연결 끊김 시 5초 대기 후 부전승
 27→ */
 28→export default class BattleGameScene extends GameScene {
 29→  private battleChannel: BattleChannel | null = null;
 30→  private roomCode: string = '';
 31→  private opponentScore: number = 0;
 32→  private opponentScoreText!: Phaser.GameObjects.Text;
 33→  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
 34→  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
 35→  private battleFinished: boolean = false;
 36→
 37→  constructor() {
 38→    super('BattleGameScene');
 39→  }
 40→
 41→  init(data: BattleInitData) {
 42→    // 대전 모드 전용 데이터 추출 (super.init 호출 전)
 43→    this.battleChannel = (data.battleChannel as BattleChannel) ?? null;
 44→    this.roomCode = data.roomCode ?? '';
 45→    this.opponentScore = 0;
 46→    this.battleFinished = false;
 47→
 48→    // 부모 init 호출: EXTREME 난이도 고정, BATTLE 모드
 49→    super.init({
 50→      gameMode: GameMode.BATTLE,
 51→      difficulty: Difficulty.EXTREME,
 52→      purePhysical: false,
 53→    });
 54→  }
 55→
 56→  create() {
 57→    super.create();
 58→
 59→    // 상대 점수 UI (HUD 바 내부, 중앙 상단)
 60→    this.opponentScoreText = this.add.text(200, 3, '상대: 0', {
 61→      fontSize: '14px',
 62→      color: '#ff6666',
 63→      fontStyle: 'bold',
 64→      stroke: '#000000',
 65→      strokeThickness: 3,
 66→    }).setOrigin(0.5, 0).setDepth(10);
 67→
 68→    // ── 배틀 채널 이벤트 리스너 ──
 69→    this.setupBattleListeners();
 70→
 71→    // 1초마다 점수 브로드캐스트
 72→    this.scoreUpdateTimer = this.time.addEvent({
 73→      delay: 1000,
 74→      callback: () => {
 75→        if (!this.gameOver && this.battleChannel) {
 76→          this.battleChannel.sendScoreUpdate(this.score);
 77→        }
 78→      },
 79→      loop: true,
 80→    });
 81→  }
 82→
 83→  private setupBattleListeners() {
 84→    if (!this.battleChannel) return;
 85→
 86→    // 상대가 보낸 똥 수신
 87→    this.battleChannel.onEvent(BattleEvent.SEND_POOP, (payload) => {
 88→      if (!this.gameOver) {
 89→        this.onReceivePoop(payload.count);
 90→      }
 91→    });
 92→
 93→    // 상대 점수 갱신
 94→    this.battleChannel.onEvent(BattleEvent.SCORE_UPDATE, (payload) => {
 95→      this.opponentScore = payload.score;
 96→      if (this.opponentScoreText?.active) {
 97→        this.opponentScoreText.setText(`상대: ${this.opponentScore}`);
 98→      }
 99→    });
100→
101→    // 상대 사망 → 즉시 승리
102→    this.battleChannel.onEvent(BattleEvent.GAME_OVER, (payload) => {
103→      if (!this.battleFinished) {
104→        this.opponentScore = payload.finalScore;
105→        this.endBattle(BattleResult.WIN);
106→      }
107→    });
108→
109→    // 상대 이탈 → 5초 대기 후 부전승
110→    this.battleChannel.onPresenceLeave(() => {
111→      if (!this.battleFinished && !this.gameOver) {
112→        this.showDisconnectWarning();
113→        this.disconnectTimer = setTimeout(() => {
114→          if (!this.battleFinished) {
115→            this.endBattle(BattleResult.DISCONNECT);
116→          }
117→        }, 5000);
118→      }
119→    });
120→
121→    // 상대 재접속 시 타이머 취소
122→    this.battleChannel.onPresenceJoin(() => {
