      fontSize: '32px',
      color: '#ff4444',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
    }).setOrigin(0.5);

    this.add.text(200, 105, 'EXTREME 난이도로 1대1 대전!', {
      fontSize: '14px',
      color: '#cccccc',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 상태 텍스트 (오버레이 위에 표시되도록 depth 설정)
    this.statusText = this.add.text(200, 400, '', {
      fontSize: '16px',
      color: '#ffffff',
      stroke: '#000',
      strokeThickness: 3,
      align: 'center',
    }).setOrigin(0.5).setDepth(10);

    // 방 코드 표시 (오버레이 위에 표시되도록 depth 설정)
    this.codeText = this.add.text(200, 280, '', {
      fontSize: '48px',
      color: '#FFD700',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 6,
      letterSpacing: 8,
    }).setOrigin(0.5).setDepth(10);

    // 방 만들기 버튼
    this.createButton(200, 220, '방 만들기', 0xe74c3c, () => this.handleCreateRoom());

    // 방 참가 버튼
    this.createButton(200, 310, '방 참가', 0x3498db, () => this.handleJoinRoom());

    // 뒤로가기 버튼
    const backBtn = this.add.text(200, 550, '← 메인 메뉴', {
      fontSize: '18px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });

    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    backBtn.on('pointerdown', () => this.goBack());

    // 유저 ID 가져오기
    const { data } = await supabase.auth.getUser();
    this.userId = data.user?.id ?? `anon-${Date.now()}`;
  }

