  private showJoinWaiting(code: string) {
    this.clearUI();

    this.ui(this.add.text(200, 220, `방 코드: ${code}`, {
      fontSize: '20px', color: '#FFD700', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 4,
    }).setOrigin(0.5));

    const statusText = this.ui(this.add.text(200, 290, '연결 완료!', {
