  1→import Phaser from 'phaser';
  2→import { BattleChannel } from '../utils/battleChannel';
  3→import { BattleEvent, BattleResult } from '../types/BattleTypes';
  4→import { GameMode, Difficulty } from '../types/GameMode';
  5→import { POOP_CONFIG } from '../config/poop';
  6→import type Poop from '../objects/Poop';
  7→import GameScene from './GameScene';
  8→
  9→interface BattleInitData {
 10→  gameMode?: string;
 11→  difficulty?: string;
 12→  purePhysical?: boolean;
 13→  roomCode?: string;
 14→  userId?: string;
 15→}
 16→
 17→/**
 18→ * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
 19→ *
 20→ * BattleMatchScene에서 roomCode/userId를 받아 새 채널을 직접 생성합니다.
 21→ * (Supabase Realtime은 리스너 등록 → subscribe 순서 필수)
 22→ */
 23→export default class BattleGameScene extends GameScene {
 24→  private battleChannel: BattleChannel | null = null;
 25→  private roomCode: string = '';
 26→  private battleUserId: string = '';
 27→  private opponentScore: number = 0;
 28→  private opponentScoreText!: Phaser.GameObjects.Text;
 29→  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
 30→  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
 31→  private battleFinished: boolean = false;
 32→
 33→  constructor() {
 34→    super('BattleGameScene');
 35→  }
 36→
 37→  init(data: BattleInitData) {
 38→    this.roomCode = data.roomCode ?? '';
 39→    this.battleUserId = data.userId ?? '';
 40→    this.opponentScore = 0;
 41→    this.battleFinished = false;
 42→    this.channelReady = false;
 43→
 44→    // 부모 init 호출: EXTREME 난이도 고정, BATTLE 모드
 45→    super.init({
 46→      gameMode: GameMode.BATTLE,
 47→      difficulty: Difficulty.EXTREME,
 48→      purePhysical: false,
 49→    });
 50→  }
 51→
 52→  create() {
 53→    super.create();
 54→
 55→    // 상대 점수 UI (HUD 바 내부, 중앙 상단)
 56→    this.opponentScoreText = this.add.text(200, 3, '상대: 0', {
 57→      fontSize: '14px',
 58→      color: '#ff6666',
 59→      fontStyle: 'bold',
 60→      stroke: '#000000',
 61→      strokeThickness: 3,
 62→    }).setOrigin(0.5, 0).setDepth(10);
 63→
 64→    // 연결 상태 표시
 65→    const connectingText = this.add.text(200, 55, '⏳ 상대와 연결 중...', {
 66→      fontSize: '13px',
 67→      color: '#ffaa00',
 68→      stroke: '#000',
 69→      strokeThickness: 3,
 70→    }).setOrigin(0.5).setDepth(10);
 71→
 72→    // 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
 73→    this.initBattleChannel(connectingText);
 74→  }
 75→
 76→  /** 채널 연결 완료 여부 (send 호출 가드) */
 77→  private channelReady: boolean = false;
 78→
 79→  /**
 80→   * 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
 81→   */
 82→  private async initBattleChannel(connectingText: Phaser.GameObjects.Text) {
 83→    this.battleChannel = new BattleChannel();
 84→    this.battleChannel.joinRoom(this.roomCode, this.battleUserId);
 85→
 86→    // 리스너 등록 (subscribe 전 — Supabase Realtime 필수 패턴)
 87→    this.setupBattleListeners();
 88→
 89→    // 구독 시작
 90→    await this.battleChannel.subscribe();
 91→    this.channelReady = true;
 92→
 93→    // 연결 완료 표시
 94→    if (connectingText?.active) {
 95→      connectingText.setText('✅ 연결 완료!');
 96→      connectingText.setColor('#00ff00');
 97→      this.time.delayedCall(1500, () => {
 98→        if (connectingText.active) connectingText.destroy();
 99→      });
100→    }
101→
102→    // 구독 완료 후 점수 타이머 시작 (구독 전 전송 방지)
103→    this.scoreUpdateTimer = this.time.addEvent({
104→      delay: 1000,
105→      callback: () => {
106→        if (!this.gameOver && this.battleChannel && this.channelReady) {
107→          this.battleChannel.sendScoreUpdate(this.score);
108→        }
109→      },
110→      loop: true,
111→    });
112→
113→    // 즉시 현재 점수 동기화
114→    this.battleChannel.sendScoreUpdate(this.score);
115→  }
116→
117→  private setupBattleListeners() {
118→    if (!this.battleChannel) return;
119→
120→    // 상대가 보낸 똥 수신
121→    this.battleChannel.onEvent(BattleEvent.SEND_POOP, (payload) => {
122→      if (!this.gameOver) {
123→        this.onReceivePoop(payload.count);
124→      }
125→    });
126→
127→    // 상대 점수 갱신
128→    this.battleChannel.onEvent(BattleEvent.SCORE_UPDATE, (payload) => {
129→      this.opponentScore = payload.score;
130→      if (this.opponentScoreText?.active) {
131→        this.opponentScoreText.setText(`상대: ${this.opponentScore}`);
132→      }
133→    });
134→
135→    // 상대 사망 → 즉시 승리
136→    this.battleChannel.onEvent(BattleEvent.GAME_OVER, (payload) => {
137→      if (!this.battleFinished) {
138→        this.opponentScore = payload.finalScore;
139→        this.endBattle(BattleResult.WIN);
140→      }
141→    });
142→
143→    // 상대 이탈 → 5초 대기 후 부전승
144→    this.battleChannel.onPresenceLeave(() => {
145→      if (!this.battleFinished && !this.gameOver) {
146→        this.showDisconnectWarning();
147→        this.disconnectTimer = setTimeout(() => {
148→          if (!this.battleFinished) {
149→            this.endBattle(BattleResult.DISCONNECT);
150→          }
151→        }, 5000);
152→      }
153→    });
154→
155→    // 상대 재접속 시 타이머 취소
156→    this.battleChannel.onPresenceJoin(() => {
157→      if (this.disconnectTimer) {
158→        clearTimeout(this.disconnectTimer);
159→        this.disconnectTimer = null;
160→        this.hideDisconnectWarning();
161→      }
162→    });
163→  }
164→
165→  /**
166→   * 특수 똥 수집 시 — 부모 처리 후 상대에게 똥 전송
167→   */
168→  protected handleSpecialCollected(
169→    poop: Phaser.Physics.Arcade.Sprite,
170→    type: import('../abilities/types').SpecialPoopType,
171→    baseScore: number,
172→    emoji: string,
173→    color: string,
174→    counterIncrement: () => void,
175→  ) {
176→    super.handleSpecialCollected(poop, type, baseScore, emoji, color, counterIncrement);
177→
178→    // 상대에게 일반 똥 1개 전송
179→    if (this.battleChannel && this.channelReady && !this.gameOver) {
180→      this.battleChannel.sendPoop(1);
181→
182→      const sendText = this.add.text(200, 150, '💩→ 상대에게 전송!', {
183→        fontSize: '16px',
184→        color: '#ff4444',
185→        fontStyle: 'bold',
186→        stroke: '#000',
187→        strokeThickness: 3,
188→      }).setOrigin(0.5).setDepth(200);
189→      this.tweens.add({
190→        targets: sendText,
191→        alpha: 0,
192→        y: 120,
193→        duration: 800,
194→        onComplete: () => sendText.destroy(),
195→      });
196→    }
197→  }
