   290→  private setupChannelListeners() {
   291→    if (!this.battleChannel) return;
   292→
   293→    // Presence join — 호스트일 때 상대 입장 UI 갱신 + 즉시 ready 전송
   294→    this.battleChannel.onPresenceJoin(() => {
   295→      if (this.isHost && !this.myReady) {
   296→        this.doSendReady();
   297→      }
   298→    });
   299→
   300→    this.battleChannel.onPresenceLeave(() => {
   301→      this.opponentReady = false;
   302→      this.ui(this.add.text(200, 420, '⚠️ 상대방이 나갔습니다', {
   303→        fontSize: '16px', color: '#ff4444',
   304→        stroke: '#000', strokeThickness: 3,
   305→      }).setOrigin(0.5));
   306→    });
   307→
   308→    // READY 수신 = 상대가 확실히 존재 + 준비 완료
   309→    // Presence join보다 READY가 먼저 올 수 있으므로, 여기서도 자신의 ready를 보냄
   310→    this.battleChannel.onEvent(BattleEvent.READY, () => {
   311→      this.opponentReady = true;
   312→      // 아직 내 ready를 안 보냈으면 즉시 보냄 (Presence 이벤트 누락 대비)
   313→      if (!this.myReady) {
   314→        this.doSendReady();
   315→      }
   316→      this.checkBothReady();
   317→    });
   318→
   319→    this.battleChannel.onEvent(BattleEvent.GAME_START, () => {
   320→      if (!this.countdownStarted) {
   321→        this.countdownStarted = true;
   322→        this.showCountdown();
   323→      }
   324→    });
   325→  }
