   327→  /** ready 전송 (UI 상태와 분리 — 어디서든 호출 가능) */
   328→  private doSendReady() {
   329→    if (!this.battleChannel || this.myReady) return;
   330→    this.myReady = true;
   331→    const charId = getSafeSelectedCharacter();
   332→    this.battleChannel.sendReady(charId);
   333→
   334→    // UI 갱신: 현재 화면 정리 → 대기 화면
   335→    this.clearUI();
   336→    this.ui(this.add.text(200, 270, '✅ 준비 완료!', {
   337→      fontSize: '24px', color: '#00ff00', fontStyle: 'bold',
   338→      stroke: '#000', strokeThickness: 4,
   339→    }).setOrigin(0.5));
   340→    this.ui(this.add.text(200, 320, '상대를 기다리는 중...', {
   341→      fontSize: '16px', color: '#ffffff',
   342→      stroke: '#000', strokeThickness: 3,
   343→    }).setOrigin(0.5));
   344→
   345→    // READY를 주기적으로 재전송 — 네트워크/타이밍 이슈로 상대가 수신 못했을 때 대비
   346→    // setInterval 사용 (Phaser 타이머는 백그라운드 탭에서 멈추므로)
   347→    this.clearReadyRetry();
   348→    this.readyRetryTimer = setInterval(() => {
   349→      if (this.countdownStarted || !this.battleChannel) {
   350→        this.clearReadyRetry();
   351→        return;
   352→      }
   353→      this.battleChannel.sendReady(charId);
   354→    }, 1500);
   355→
   356→    this.checkBothReady();
   357→  }
