   359→  private clearReadyRetry() {
   360→    if (this.readyRetryTimer) {
   361→      clearInterval(this.readyRetryTimer);
   362→      this.readyRetryTimer = null;
   363→    }
   364→  }
   365→
   366→  private checkBothReady() {
   367→    if (this.myReady && this.opponentReady && this.isHost && !this.countdownStarted) {
   368→      this.countdownStarted = true;
   369→      this.battleChannel?.sendGameStart(Date.now());
   370→      this.showCountdown();
   371→    }
   372→  }
