   376→  private showCountdown() {
   377→    this.clearUI();
   378→
   379→    let count = 3;
   380→    const countText = this.ui(this.add.text(200, 280, `${count}`, {
   381→      fontSize: '90px', color: '#ff4444', fontStyle: 'bold',
   382→      stroke: '#000', strokeThickness: 8,
   383→    }).setOrigin(0.5));
   384→
   385→    const timer = this.time.addEvent({
   386→      delay: 1000,
   387→      callback: () => {
   388→        count--;
   389→        if (count > 0) {
   390→          (countText as Phaser.GameObjects.Text).setText(`${count}`);
   391→        } else {
   392→          (countText as Phaser.GameObjects.Text).setText('GO!');
   393→          (countText as Phaser.GameObjects.Text).setColor('#00ff00');
   394→          timer.remove();
   395→          this.time.delayedCall(500, () => this.goToBattle());
   396→        }
   397→      },
   398→      repeat: 2,
   399→    });
   400→  }
