   426→  private async goBack() {
   427→    this.clearReadyRetry();
   428→    this.removeInput();
   429→    if (this.battleChannel) {
   430→      await this.battleChannel.destroy();
   431→      this.battleChannel = null;
   432→    }
   433→    this.scene.start('ModeSelectScene');
   434→  }
   435→
   436→  shutdown() {
