   105→    // 구독 완료 후 점수 타이머 시작 (구독 전 전송 방지)
   106→    this.scoreUpdateTimer = this.time.addEvent({
   107→      delay: 1000,
   108→      callback: () => {
   109→        if (!this.gameOver && this.battleChannel && this.channelReady) {
   110→          this.battleChannel.sendScoreUpdate(this.score);
   111→        }
   112→      },
