   137→
   138→    // 상대 사망 → 즉시 승리
   139→    this.battleChannel.onEvent(BattleEvent.GAME_OVER, (payload) => {
   140→      if (!this.battleFinished) {
   141→        this.opponentScore = payload.finalScore;
   142→        // 패배 측이 최종 점수를 표시할 수 있도록 현재 점수를 한 번 더 전송
   143→        if (this.channelReady && this.battleChannel) {
   144→          this.battleChannel.sendScoreUpdate(this.score);
   145→        }
   146→        this.endBattle(BattleResult.WIN);
   147→      }
   148→    });
   149→
   150→    // 상대 이탈 → 5초 대기 후 부전승
   151→    this.battleChannel.onPresenceLeave(() => {
