    if (this.channelReady && this.battleChannel) {
      this.battleChannel.sendScoreUpdate(this.score); // final score sync
    }
    this.endBattle(BattleResult.WIN);
  }
});

// endBattle:
private endBattle(result: BattleResult) {
  if (this.battleFinished) return;
  this.battleFinished = true;
  if (this.disconnectTimer) { clearTimeout(this.disconnectTimer); this.disconnectTimer = null; }
  this.hideDisconnectWarning();
  if (result === BattleResult.WIN || result === BattleResult.DISCONNECT) {
    this.gameOver = true;
    if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
    this.physics.pause();
    this.sound.stopAll();
  }
  this.time.delayedCall(1000, () => {
    this.scene.start('BattleResultScene', { result, myScore: this.score, opponentScore: this.opponentScore, roomCode: this.roomCode });
  });
}

// shutdown:
shutdown() {
  if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
  if (this.disconnectTimer) { clearTimeout(this.disconnectTimer); this.disconnectTimer = null; }
  if (this.battleChannel) { this.battleChannel.destroy(); this.battleChannel = null; }
}
