    18→ * 대전 게임 씬 — GameScene을 상속하여 코드 재사용
    19→ *
    20→ * BattleMatchScene에서 roomCode/userId를 받아 새 채널을 직접 생성합니다.
    21→ * (Supabase Realtime은 리스너 등록 → subscribe 순서 필수)
    22→ */
    23→export default class BattleGameScene extends GameScene {
    24→  private battleChannel: BattleChannel | null = null;
    25→  private roomCode: string = '';
    26→  private battleUserId: string = '';
    27→  private opponentScore: number = 0;
    28→  private opponentScoreText!: Phaser.GameObjects.Text;
    29→  private scoreUpdateTimer!: Phaser.Time.TimerEvent;
    30→  private disconnectTimer: ReturnType<typeof setTimeout> | null = null;
    31→  private battleFinished: boolean = false;
    32→
    33→  constructor() {
    34→    super('BattleGameScene');
    35→  }
    36→
    37→  init(data: BattleInitData) {
    38→    this.roomCode = data.roomCode ?? '';
    39→    this.battleUserId = data.userId ?? '';
    40→    this.opponentScore = 0;
    41→    this.battleFinished = false;
    42→    this.channelReady = false;
    43→
    44→    // 부모 init 호출: EXTREME 난이도 고정, BATTLE 모드
    45→    super.init({
    46→      gameMode: GameMode.BATTLE,
    47→      difficulty: Difficulty.EXTREME,
    48→      purePhysical: false,
    49→    });
    50→  }
    51→
    52→  create() {
    53→    super.create();
    54→
    55→    // 대전 모드에서는 최고 기록 표시 불필요
    56→    if (this.highScoreText) this.highScoreText.setVisible(false);
    57→
    58→    // 상대 점수 UI (HUD 바 내부, 중앙 상단)
    59→    this.opponentScoreText = this.add.text(200, 3, '상대: 0', {
    60→      fontSize: '14px',
    61→      color: '#ff6666',
    62→      fontStyle: 'bold',
    63→      stroke: '#000000',
    64→      strokeThickness: 3,
    65→    }).setOrigin(0.5, 0).setDepth(10);
    66→
    67→    // 연결 상태 표시
    68→    const connectingText = this.add.text(200, 55, '⏳ 상대와 연결 중...', {
    69→      fontSize: '13px',
    70→      color: '#ffaa00',
    71→      stroke: '#000',
    72→      strokeThickness: 3,
    73→    }).setOrigin(0.5).setDepth(10);
    74→
    75→    // 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
    76→    this.initBattleChannel(connectingText);
    77→  }
    78→
    79→  /** 채널 연결 완료 여부 (send 호출 가드) */
    80→  private channelReady: boolean = false;
    81→
    82→  /**
    83→   * 새 채널 생성 → 리스너 등록 → subscribe → 점수 타이머 시작
    84→   */
    85→  private async initBattleChannel(connectingText: Phaser.GameObjects.Text) {
    86→    this.battleChannel = new BattleChannel();
    87→    this.battleChannel.joinRoom(this.roomCode, this.battleUserId);
    88→
    89→    // 리스너 등록 (subscribe 전 — Supabase Realtime 필수 패턴)
    90→    this.setupBattleListeners();
    91→
    92→    // 구독 시작
    93→    await this.battleChannel.subscribe();
    94→    this.channelReady = true;
    95→
    96→    // 연결 완료 표시
    97→    if (connectingText?.active) {
    98→      connectingText.setText('✅ 연결 완료!');
    99→      connectingText.setColor('#00ff00');
   100→      this.time.delayedCall(1500, () => {
   101→        if (connectingText.active) connectingText.destroy();
   102→      });
   103→    }
   104→
   105→    // 구독 완료 후 점수 타이머 시작 (구독 전 전송 방지)
   106→    this.scoreUpdateTimer = this.time.addEvent({
   107→      delay: 1000,
   108→      callback: () => {
   109→        if (!this.gameOver && this.battleChannel && this.channelReady) {
   110→          this.battleChannel.sendScoreUpdate(this.score);
   111→        }
   112→      },
   113→      loop: true,
   114→    });
   115→
   116→    // 즉시 현재 점수 동기화
   117→    this.battleChannel.sendScoreUpdate(this.score);
   118→  }
   119→
   120→  private setupBattleListeners() {
   121→    if (!this.battleChannel) return;
   122→
   123→    // 상대가 보낸 똥 수신
   124→    this.battleChannel.onEvent(BattleEvent.SEND_POOP, (payload) => {
   125→      if (!this.gameOver) {
   126→        this.onReceivePoop(payload.count);
   127→      }
   128→    });
   129→
   130→    // 상대 점수 갱신
   131→    this.battleChannel.onEvent(BattleEvent.SCORE_UPDATE, (payload) => {
   132→      this.opponentScore = payload.score;
   133→      if (this.opponentScoreText?.active) {
   134→        this.opponentScoreText.setText(`상대: ${this.opponentScore}`);
   135→      }
   136→    });
   137→
   138→    // 상대 사망 → 즉시 승리
   139→    this.battleChannel.onEvent(BattleEvent.GAME_OVER, (payload) => {
   140→      if (!this.battleFinished) {
   141→        this.opponentScore = payload.finalScore;
   142→        // 패배 측이 최종 점수를 표시할 수 있도록 현재 점수를 한 번 더 전송
   143→        if (this.channelReady && this.battleChannel) {
   144→          this.battleChannel.sendScoreUpdate(this.score);
   145→        }
   146→        this.endBattle(BattleResult.WIN);
   147→      }
   148→    });
   149→
   150→    // 상대 이탈 → 5초 대기 후 부전승
   151→    this.battleChannel.onPresenceLeave(() => {
   152→      if (!this.battleFinished && !this.gameOver) {
   153→        this.showDisconnectWarning();
   154→        this.disconnectTimer = setTimeout(() => {
   155→          if (!this.battleFinished) {
   156→            this.endBattle(BattleResult.DISCONNECT);
   157→          }
   158→        }, 5000);
   159→      }
   160→    });
   161→
   162→    // 상대 재접속 시 타이머 취소
   163→    this.battleChannel.onPresenceJoin(() => {
   164→      if (this.disconnectTimer) {
   165→        clearTimeout(this.disconnectTimer);
   166→        this.disconnectTimer = null;
   167→        this.hideDisconnectWarning();
   168→      }
   169→    });
   170→  }
   171→
   172→  /**
   173→   * 특수 똥 수집 시 — 부모 처리 후 상대에게 똥 전송
   174→   */
   175→  protected handleSpecialCollected(
   176→    poop: Phaser.Physics.Arcade.Sprite,
   177→    type: import('../abilities/types').SpecialPoopType,
   178→    baseScore: number,
   179→    emoji: string,
   180→    color: string,
   181→    counterIncrement: () => void,
   182→  ) {
   183→    super.handleSpecialCollected(poop, type, baseScore, emoji, color, counterIncrement);
   184→
   185→    // 상대에게 일반 똥 1개 전송
   186→    if (this.battleChannel && this.channelReady && !this.gameOver) {
   187→      this.battleChannel.sendPoop(1);
   188→
   189→      const sendText = this.add.text(200, 150, '💩→ 상대에게 전송!', {
   190→        fontSize: '16px',
   191→        color: '#ff4444',
   192→        fontStyle: 'bold',
   193→        stroke: '#000',
   194→        strokeThickness: 3,
   195→      }).setOrigin(0.5).setDepth(200);
   196→      this.tweens.add({
   197→        targets: sendText,
   198→        alpha: 0,
   199→        y: 120,
   200→        duration: 800,
   201→        onComplete: () => sendText.destroy(),
   202→      });
   203→    }
   204→  }
   205→
   206→  /**
   207→   * 피격 시 — 부모 처리 후 상대에게 사망 알림
   208→   */
   209→  protected hitPoop(
   210→    player: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile,
   211→    poop: Phaser.Types.Physics.Arcade.GameObjectWithBody | Phaser.Tilemaps.Tile
   212→  ) {
   213→    const wasGameOver = this.gameOver;
   214→    super.hitPoop(player, poop);
   215→
   216→    if (!wasGameOver && this.gameOver && this.battleChannel && this.channelReady) {
   217→      this.battleChannel.sendGameOver(this.score);
   218→      if (!this.battleFinished) {
   219→        this.endBattle(BattleResult.LOSE);
   220→      }
   221→    }
   222→  }
   223→
   224→  /**
   225→   * 게임오버 UI — 대전 모드에서는 endBattle()이 대신 처리
   226→   */
   227→  protected async showGameOverUI(_isNewRecord: boolean) {
   228→    // 대전 모드에서는 리더보드/SKOR 제출 없이 결과 씬으로 전환
   229→  }
   230→
   231→  /**
   232→   * 상대가 보낸 똥 수신 — 랜덤 위치에 일반 똥 생성 + 빨간 경고
   233→   */
   234→  private onReceivePoop(count: number) {
   235→    const fallSpeed = this.difficultyConfig.baseSpeed +
   236→      (this.difficultyLevel * POOP_CONFIG.normal.speedIncrement);
   237→
   238→    for (let i = 0; i < count; i++) {
   239→      const x = Phaser.Math.Between(15, 385);
   240→      const y = Phaser.Math.Between(-100, -20);
   241→      const poop = this.poops.get() as Poop;
   242→      if (!poop) continue;
   243→      poop.reinit(x, y, Difficulty.EXTREME);
   244→      if (poop.body) {
   245→        poop.body.velocity.y = fallSpeed * 1.2;
   246→      }
   247→      poop.setTint(0xff0000);
   248→      this.time.delayedCall(300, () => {
   249→        if (poop.active) poop.clearTint();
   250→      });
   251→    }
   252→
   253→    this.showReceiveWarning();
   254→  }
   255→
   256→  private showReceiveWarning() {
   257→    const border = this.add.rectangle(200, 300, 400, 600)
   258→      .setStrokeStyle(6, 0xff0000)
   259→      .setFillStyle(0xff0000, 0.1)
   260→      .setDepth(150);
   261→
   262→    this.tweens.add({
   263→      targets: border,
   264→      alpha: 0,
   265→      duration: 400,
   266→      onComplete: () => border.destroy(),
   267→    });
   268→
   269→    const warningText = this.add.text(200, 60, '⚠️ 공격 받음!', {
   270→      fontSize: '18px',
   271→      color: '#ff0000',
   272→      fontStyle: 'bold',
   273→      stroke: '#000',
   274→      strokeThickness: 4,
   275→    }).setOrigin(0.5).setDepth(200);
   276→    this.tweens.add({
   277→      targets: warningText,
   278→      alpha: 0,
   279→      y: 45,
   280→      duration: 800,
   281→      onComplete: () => warningText.destroy(),
   282→    });
   283→  }
   284→
   285→  private disconnectWarningText: Phaser.GameObjects.Text | null = null;
   286→
   287→  private showDisconnectWarning() {
   288→    if (this.disconnectWarningText) return;
   289→    this.disconnectWarningText = this.add.text(200, 200, '⚠️ 상대방 연결 끊김\n5초 후 부전승...', {
   290→      fontSize: '18px',
   291→      color: '#ffaa00',
   292→      fontStyle: 'bold',
   293→      stroke: '#000',
   294→      strokeThickness: 4,
   295→      align: 'center',
   296→    }).setOrigin(0.5).setDepth(200);
   297→  }
   298→
   299→  private hideDisconnectWarning() {
   300→    if (this.disconnectWarningText) {
   301→      this.disconnectWarningText.destroy();
   302→      this.disconnectWarningText = null;
   303→    }
   304→  }
   305→
   306→  private endBattle(result: BattleResult) {
   307→    if (this.battleFinished) return;
   308→    this.battleFinished = true;
   309→
   310→    if (this.disconnectTimer) {
   311→      clearTimeout(this.disconnectTimer);
   312→      this.disconnectTimer = null;
   313→    }
   314→
   315→    this.hideDisconnectWarning();
   316→
   317→    if (result === BattleResult.WIN || result === BattleResult.DISCONNECT) {
   318→      this.gameOver = true;
   319→      if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
   320→      this.physics.pause();
   321→      this.sound.stopAll();
   322→    }
   323→
   324→    this.time.delayedCall(1000, () => {
   325→      this.scene.start('BattleResultScene', {
   326→        result,
   327→        myScore: this.score,
   328→        opponentScore: this.opponentScore,
   329→        roomCode: this.roomCode,
   330→      });
   331→    });
   332→  }
   333→
   334→  shutdown() {
   335→    if (this.scoreUpdateTimer) this.scoreUpdateTimer.remove();
   336→    if (this.disconnectTimer) {
   337→      clearTimeout(this.disconnectTimer);
   338→      this.disconnectTimer = null;
   339→    }
   340→    // 채널 정리
   341→    if (this.battleChannel) {
   342→      this.battleChannel.destroy();
   343→      this.battleChannel = null;
   344→    }
   345→  }
   346→}
