     1→import { type RealtimeChannel } from '@supabase/supabase-js';
     2→import { supabase } from './supabase';
     3→import {
     4→  BattleEvent,
     5→  type ReadyPayload,
     6→  type GameStartPayload,
     7→  type SendPoopPayload,
     8→  type ScoreUpdatePayload,
     9→  type GameOverPayload,
    10→} from '../types/BattleTypes';
    11→
    12→type BattlePayloadMap = {
    13→  [BattleEvent.READY]: ReadyPayload;
    14→  [BattleEvent.GAME_START]: GameStartPayload;
    15→  [BattleEvent.SEND_POOP]: SendPoopPayload;
    16→  [BattleEvent.SCORE_UPDATE]: ScoreUpdatePayload;
    17→  [BattleEvent.GAME_OVER]: GameOverPayload;
    18→};
    19→
    20→/**
    21→ * Supabase Realtime Broadcast 채널 래퍼
    22→ *
    23→ * ⚠️ Supabase Realtime은 `.on()` 리스너를 `.subscribe()` 전에 등록해야 합니다.
    24→ * 따라서 채널 생성(createRoom/joinRoom) → 리스너 등록(onEvent 등) → 구독(subscribe) 순서로 호출하세요.
    25→ */
    26→export class BattleChannel {
    27→  private channel: RealtimeChannel | null = null;
    28→  private roomCode: string = '';
    29→  private userId: string = '';
    30→
    31→  /** 4자리 랜덤 방 코드 생성 */
    32→  static generateRoomCode(): string {
    33→    const chars = 'REDACTED'; // 혼동 문자(I,O,0,1) 제외
    34→    let code = '';
    35→    for (let i = 0; i < 4; i++) {
    36→      code += chars[Math.floor(Math.random() * chars.length)];
    37→    }
    38→    return code;
    39→  }
    40→
    41→  /** 방 생성 (호스트) — 채널만 생성, subscribe는 별도 호출 */
    42→  createRoom(code: string, userId: string): void {
    43→    this.roomCode = code;
    44→    this.userId = userId;
    45→    this.createChannel();
    46→  }
    47→
    48→  /** 방 참가 (게스트) — 채널만 생성, subscribe는 별도 호출 */
    49→  joinRoom(code: string, userId: string): void {
    50→    this.roomCode = code;
    51→    this.userId = userId;
    52→    this.createChannel();
    53→  }
    54→
    55→  /** 채널 객체만 생성 (구독하지 않음) */
    56→  private createChannel(): void {
    57→    this.channel = supabase.channel(`battle-room:${this.roomCode}`, {
    58→      config: {
    59→        broadcast: { self: false },
    60→        presence: { key: this.userId },
    61→      },
    62→    });
    63→  }
    64→
    65→  /**
    66→   * 리스너 등록 완료 후 호출 — 실제 WebSocket 구독 시작 + Presence track
    67→   * 반드시 onEvent/onPresenceJoin/onPresenceLeave 등록 후에 호출하세요.
    68→   */
    69→  async subscribe(): Promise<void> {
    70→    if (!this.channel) return;
    71→    return new Promise((resolve) => {
    72→      this.channel!.subscribe(async (status) => {
    73→        if (status === 'SUBSCRIBED') {
    74→          await this.channel!.track({ userId: this.userId, joinedAt: Date.now() });
    75→          resolve();
    76→        }
    77→      });
    78→    });
    79→  }
    80→
    81→  /** Broadcast 이벤트 리스너 등록 (subscribe 전에 호출) */
    82→  onEvent<E extends BattleEvent>(event: E, callback: (payload: BattlePayloadMap[E]) => void): void {
    83→    if (!this.channel) return;
    84→    this.channel.on('broadcast', { event }, (msg) => {
    85→      callback(msg.payload as BattlePayloadMap[E]);
    86→    });
    87→  }
    88→
    89→  /** Presence 동기화 — 상대 참가 감지 (subscribe 전에 호출) */
    90→  onPresenceJoin(callback: (userId: string) => void): void {
    91→    if (!this.channel) return;
    92→    this.channel.on('presence', { event: 'join' }, ({ newPresences }) => {
    93→      for (const p of newPresences) {
    94→        const uid = (p as Record<string, unknown>).userId as string;
    95→        if (uid && uid !== this.userId) {
    96→          callback(uid);
    97→        }
    98→      }
    99→    });
   100→  }
   101→
   102→  /** Presence 동기화 — 상대 이탈 감지 (subscribe 전에 호출) */
   103→  onPresenceLeave(callback: (userId: string) => void): void {
   104→    if (!this.channel) return;
   105→    this.channel.on('presence', { event: 'leave' }, ({ leftPresences }) => {
   106→      for (const p of leftPresences) {
   107→        const uid = (p as Record<string, unknown>).userId as string;
   108→        if (uid && uid !== this.userId) {
   109→          callback(uid);
   110→        }
   111→      }
   112→    });
   113→  }
   114→
   115→  /** 현재 Presence 상태에서 상대방이 있는지 확인 */
   116→  getOpponentPresence(): string | null {
   117→    if (!this.channel) return null;
   118→    const state = this.channel.presenceState();
   119→    for (const key of Object.keys(state)) {
   120→      if (key !== this.userId) return key;
   121→    }
   122→    return null;
   123→  }
   124→
   125→  // ── 이벤트 송신 메서드 ──
   126→
   127→  sendReady(characterId: string): void {
   128→    this.broadcast(BattleEvent.READY, { userId: this.userId, characterId });
   129→  }
   130→
   131→  sendGameStart(timestamp: number): void {
   132→    this.broadcast(BattleEvent.GAME_START, { timestamp });
   133→  }
   134→
   135→  sendPoop(count: number): void {
   136→    this.broadcast(BattleEvent.SEND_POOP, { count });
   137→  }
   138→
   139→  sendScoreUpdate(score: number): void {
   140→    this.broadcast(BattleEvent.SCORE_UPDATE, { score });
   141→  }
   142→
   143→  sendGameOver(finalScore: number): void {
   144→    this.broadcast(BattleEvent.GAME_OVER, { userId: this.userId, finalScore });
   145→  }
   146→
   147→  private broadcast<E extends BattleEvent>(event: E, payload: BattlePayloadMap[E]): void {
   148→    if (!this.channel) return;
   149→    this.channel.send({
   150→      type: 'broadcast',
   151→      event,
   152→      payload,
   153→    });
   154→  }
   155→
   156→  /** 채널 정리 (비동기 — untrack 후 채널 제거) */
   157→  async destroy(): Promise<void> {
   158→    if (this.channel) {
   159→      await this.channel.untrack();
   160→      supabase.removeChannel(this.channel);
   161→      this.channel = null;
   162→    }
   163→  }
   164→
   165→  /**
   166→   * 채널 즉시 제거 (동기 — 씬 전환 전 호출용)
   167→   *
   168→   * supabase.channel()은 싱글턴이므로 removeChannel을 먼저 호출해야
   169→   * 다음 씬에서 같은 이름으로 새 채널을 생성할 수 있다.
   170→   */
   171→  destroyImmediate(): void {
   172→    if (this.channel) {
   173→      supabase.removeChannel(this.channel);
   174→      this.channel = null;
   175→    }
   176→  }
   177→
   178→  get code(): string {
   179→    return this.roomCode;
   180→  }
   181→
   182→  get myUserId(): string {
   183→    return this.userId;
   184→  }
   185→}
